DROP TABLE IF EXISTS preorders CASCADE;
CREATE TABLE preorders (
  id                    VARCHAR(40) NOT NULL PRIMARY KEY,
  order_number          VARCHAR(40) NOT NULL UNIQUE,
  tourist_id            VARCHAR(40) NOT NULL,
  vendor_id             VARCHAR(40) NOT NULL,
  product_id            VARCHAR(40) NOT NULL,
  destination_id        VARCHAR(40) NULL,
  pickup_location       VARCHAR(200) NOT NULL,
  pickup_date           DATE NOT NULL,
  pickup_time           VARCHAR(30) NOT NULL,
  quantity              INT NOT NULL DEFAULT 1,
  unit_price            DECIMAL(10,2) NOT NULL,
  total_amount          DECIMAL(10,2) NOT NULL,
  advance_percent       DECIMAL(5,2) NOT NULL DEFAULT 30,
  advance_paid          DECIMAL(10,2) NOT NULL DEFAULT 0,
  commission_percent    DECIMAL(5,2) NOT NULL DEFAULT 10,
  advance_status VARCHAR(40) NOT NULL DEFAULT 'held' CHECK (advance_status IN ('held','released','refunded')),
  remaining_amount      DECIMAL(10,2) NOT NULL DEFAULT 0,
  advance_payment_method VARCHAR(40) NULL CHECK (advance_payment_method IN ('bkash','nagad','card')),
  pickup_payment_method VARCHAR(40) NULL CHECK (pickup_payment_method IN ('bkash','nagad','card','cash')),
  status VARCHAR(40) NOT NULL DEFAULT 'confirmed' CHECK (status IN ('confirmed','advance_paid','vendor_accepted','preparing','ready_for_pickup','arrived','qr_verified','pickup_payment_pending','picked_up','completed','cancelled','refunded')),
  qr_code               VARCHAR(255) NOT NULL,
  preparation_time      VARCHAR(60) NULL,
  notes                 TEXT NULL,
  cancellation_reason   VARCHAR(255) NULL,
  refund_amount         DECIMAL(10,2) NULL,
  advance_payer_phone   VARCHAR(20) NULL,
  advance_transaction_id VARCHAR(40) NULL,
  pickup_payer_phone    VARCHAR(20) NULL,
  pickup_transaction_id VARCHAR(40) NULL,
  created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (tourist_id) REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (vendor_id) REFERENCES vendors(user_id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  FOREIGN KEY (destination_id) REFERENCES heritage_places(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED
);
